ansform:translate(-50%,-50%);z-index:2;display:flex;align-items:center;gap:6px;padding:7px 10px 7px 7px;background:#101725e8;border:1px solid #f1cb8799;border-radius:25px;color:#fff5e2;font:800 11px 'Nunito';min-height:44px;box-shadow:0 4px 16px #0007;white-space:nowrap}.escape .hotspot .dot{display:grid;place-items:center;width:27px;height:27px;border-radius:50%;border:1px solid #f4cb86;color:#ffcf81;font-size:17px}.escape .hotspot:hover,.escape .hotspot:focus-visible{background:#3b3020}.escape .hotspot.found{border-color:#96c8b9}.escape .hotspot.found .dot{color:#b4e2ce;border-color:#9ac1b1}.escape .dust{position:absolute;width:3px;height:3px;background:#ffd58a8f;border-radius:50%;left:35%;top:68%;pointer-events:none;animation:drift 9s ease-in-out infinite}.escape .dust:nth-of-type(2){left:67%;top:34%;animation-delay:-3s}.escape .dust:nth-of-type(3){left:54%;top:79%;animation-delay:-6s}@keyframes drift{50%{transform:translate(24px,-35px);opacity:.15}}.escape .journal{background:#172131;border:1px solid #38465a;border-radius:16px;overflow:hidden}.escape .journal-top{padding:19px 20px 13px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #ffffff10}.escape .journal-top h2{margin:0;font-size:17px;letter-spacing:0}.escape .journal-top span{font-size:12px;color:#d8b981}.escape .note{padding:18px 20px}.escape .note h3{margin:0 0 8px;font-size:18px}.escape .note p{color:#d0d5df;line-height:1.65;font-size:14px;margin:0}.escape .quote{margin:15px 0 0;padding:12px 14px;border-left:2px solid #d5ae6f;color:#ffdfaa;background:#ffffff04;font-size:15px;line-height:1.6}.escape .passage{margin:0 20px 20px;padding-top:12px;border-top:1px solid #ffffff15}.escape .passage summary{font-size:13px;cursor:pointer;color:#f1d1a0;padding:4px 0}.escape .passage p{font-size:15px;line-height:1.75;color:#e0e3e9;margin-bottom:0}.escape .puzzle{margin-top:20px;padding:21px;background:linear-gradient(120deg,#1b2737,#17212e);border:1px solid #394859;border-radius:16px}.escape .puzzle h2{font-size:22px;margin:0 0 5px}.escape .puzzle p{color:#c6cfda;font-size:14px;line-height:1.6;margin:7px 0 13px}.escape .fragment-list,.escape .answer-list{display:flex;flex-wrap:wrap;gap:8px;min-height:48px}.escape .answer-list{padding:11px;background:#0c1522;border:1px dashed #70839b;border-radius:10px;margin:12px 0}.escape .tile{min-height:44px;padding:10px 13px;background:#2c3c51;color:#f2e9db;border:1px solid #738197;border-radius:9px;font:700 14px 'Nunito';text-align:left}.escape .tile:hover{background:#3b4d64}.escape .answer-list .tile{background:#4a3921;border-color:#d5ae6f}.escape .actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:15px}.escape .btn{margin:0;background:#edbd72;border-color:#edbd72;border-radius:10px;box-shadow:0 3px 0 #99713e;color:#221a10!important;font-size:14px}.escape .btn:hover{background:#f4cb87;border-color:#f4cb87;color:#221a10!important;box-shadow:0 4px 0 #99713e}.escape .btn.btn-ghost{background:transparent;color:#efd6b3!important;border-color:#a191784d;box-shadow:none}.escape .feedback{min-height:23px;font-size:13px;color:#f6dba4;margin-top:12px}.escape .hint{color:#efd6b3!important;padding:10px;border-left:2px solid #d6ac70;margin-top:15px!important;background:#ffffff05}.escape .dials{display:flex;gap:9px;margin:16px 0}.escape .dial{flex:1;min-width:0;min-height:86px;border:1px solid #bd9863;border-radius:11px;background:linear-gradient(#5b4d36,#272421 45%,#423526);color:#ffe7bc;box-shadow:inset 0 3px 9px #0005;font:700 20px 'Outfit'}.escape .dial small{display:block;margin-top:8px;color:#d5cbbd;font:700 10px 'Nunito'}.escape .tile[aria-pressed=true]{outline:2px solid #e5b776;background:#5a442a}.escape .targets{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:13px}.escape .target{min-height:84px;border:1px dashed #8294a9;border-radius:10px;background:#121c2a;color:#e7e4dd;padding:12px;font:700 13px 'Nunito'}.escape .target.placed{border-style:solid;border-color:#92c1ae;background:#193a32;color:#caeddf}.escape .save-row{color:#b5bfce;font-size:11px;display:flex;align-items:center;gap:8px;margin-top:17px;min-height:30px}.escape .save-row button{font:inherit;padding:8px;background:#e1b578;color:#221b10;border:0;border-radius:6px}.escape .who{font-size:11px;color:#a9b5c6;margin-left:auto}.escape .story-disclaimer{font-size:11px;line-height:1.6;color:#a2aec0;margin:15px 0}.escape .story-disclaimer a{color:#dbc49f}.escape .ov{position:fixed;inset:0;z-index:50;display:flex;align-items:center;justify-content:center;padding:24px;background:#07101ccf;backdrop-filter:blur(6px);visibility:hidden;opacity:0;pointer-events:none}.escape .ov.show{visibility:visible;opacity:1;pointer-events:auto}.escape .card{width:100%;max-width:530px;max-height:90dvh;overflow:auto;border-radius:20px;background:#152132;border:1px solid #9a805b70;box-shadow:0 30px 80px #0008;padding:34px;text-align:left}.escape .card h2{color:#f5eee3;font-size:clamp(28px,4vw,43px);line-height:1.05;margin:12px 0 18px}.escape .card p{color:#c9d2df;font-size:15px;line-height:1.7}.escape .card .btn{margin-top:12px}.escape .card input{width:100%;padding:14px;border-radius:9px;background:#0a1421;color:#fff;border:1px solid #708096;font:16px 'Nunito'}.escape .genre-tag{color:#e8bc79}.escape .small{font-size:11px!important}.escape .small a{color:#f0ce97}.escape .sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0)}.escape .intro-scene{background:linear-gradient(90deg,#07101be8,#0d152b80),url('/kids-assets/escape/prison-v1.jpg') center/cover}.escape .intro-scene .card{background:#0c182be8;border-color:#dbb88455}.escape .chapter-chips{display:flex;gap:14px;color:#b9c4d3;font-size:11px;margin:20px 0}.escape .card .quiet-notice{background:#273448;color:#f5deb7}.escape>.quiet-notice{margin:7px 20px;background:#273448;color:#f5deb7}.escape .final-verse{font-size:21px!important;color:#f5d9ac!important;padding-left:18px;border-left:2px solid #c39c60}.escape .finish-mark{color:#b5e1cc;letter-spacing:.16em;font-size:11px;font-weight:800}.escape .saved-note{font-size:11px!important;color:#a9bacd!important}
@media(max-width:980px){.escape .layout{display:flex;flex-direction:column;gap:16px}.escape .layout>div{display:contents}.escape .scene{order:0;width:100%}.escape .scene-caption{order:1;margin:0}.escape .journal{order:2;width:100%}.escape .puzzle{order:3;width:100%;margin-top:0}.escape .journal{margin-top:0}.escape .scene{max-height:none}.escape header{padding:14px 18px}.escape main{padding:20px}.escape .journal .note{padding-bottom:12px}.escape .journal .passage{margin-bottom:15px}}
@media(max-width:540px){.escape header b{font-size:13px}.escape header.top a{font-size:11px}.escape .header-tools{gap:4px}.escape .plain{font-size:11px;padding:8px 10px}.escape main{padding:18px 12px 30px}.escape .hotspot{font-size:9px;padding:4px 6px;gap:3px;min-height:44px}.escape .hotspot .dot{width:20px;height:20px;font-size:13px}.escape .hotspot[data-object=bench]{left:82%!important}.escape .scene{border-radius:12px}.escape .puzzle{padding:16px}.escape .card{padding:26px}.escape .targets{gap:6px}.escape .target{font-size:11px;padding:8px}.escape .dial{font-size:18px;min-height:75px}.escape .scene-caption{font-size:13px}.escape .save-row{flex-wrap:wrap}.escape .who{margin-left:0}.escape .chapter-track span{width:20px}}
