<body class="kids escape">
<header class="top"><a href="{{ route('kids') }}">← Games</a><b>Midnight in Philippi</b><div class="header-tools"><button class="plain" id="soundToggle" aria-pressed="false">Sound off</button><button class="plain" id="helpButton">Help</button></div></header>
<p class="quiet-notice" data-quiet-notice role="status" hidden></p>
<main>
  <div class="chapter-heading"><div><span class="overline" id="roomPlace">ACTS 16 · AN INTERACTIVE STORY</span><h1 id="roomTitle">The midnight song</h1></div><div class="chapter-track" id="chapterTrack" aria-label="Room 1 of 3"><span class="done"></span><span></span><span></span></div></div>
  <div class="layout">
    <div>
      <div class="scene" id="scene"><img id="sceneArt" src="/kids-assets/escape/prison-v1.jpg" alt="Moonlit prison room with a window, parchment, and bench" width="1672" height="941"><i class="dust" aria-hidden="true"></i><i class="dust" aria-hidden="true"></i><i class="dust" aria-hidden="true"></i><div id="hotspots"></div></div>
      <p id="roomIntro" class="scene-caption"></p>
      <section class="puzzle" aria-labelledby="puzzleTitle"><span class="overline" id="roomGoal"></span><h2 id="puzzleTitle">Restore the verse</h2><p id="puzzleInstructions"></p><div id="puzzleBody"></div><div class="actions"><button class="btn" id="checkPuzzle" disabled>Check the verse</button><button class="plain" id="hintButton">Need a hint?</button></div><p id="hintText" class="hint" hidden></p><div id="puzzleFeedback" class="feedback" role="status"></div></section>
    </div>
    <aside class="journal" aria-label="Clue journal"><div class="journal-top"><h2>Your field notes</h2><span id="clueCount">0 / 3 clues</span></div><div class="note"><h3 id="clueTitle">Search the scene</h3><p id="clueText">Tap a glowing marker to investigate an object. Each discovery stays in your journal.</p><blockquote class="quote" id="clueQuote" hidden></blockquote><div id="collectedClues" class="actions"></div></div><details class="passage" id="passage"><summary id="passageRef">Read Acts 16:25</summary><p id="passageText"></p></details></aside>
  </div>
  <div class="save-row"><span id="saveStatus" role="status"></span><button id="retrySave" hidden>Retry saving</button><span id="who" class="who"></span></div>
  <p class="story-disclaimer">A puzzle adventure inspired by Acts 16:25–34. Objects and puzzles are imagined; the Scripture excerpts are from the KJV. <a href="https://www.biblegateway.com/passage/?search=Acts%2016%3A25-34&amp;version=KJV" target="_blank" rel="noopener">Read the full account ↗</a></p>
</main>
@include('kids.player-gate')
<div class="ov intro-scene" id="introOv" aria-labelledby="introTitle"><div class="card"><span class="overline">BIBLE ESCAPE ROOM · CHAPTER ONE</span><h2 id="introTitle">Midnight.<br>A prison.<br>An unexpected hope.</h2><p>Search the room. Follow the Scripture clues. Discover why an open door is only the beginning.</p><div class="chapter-chips"><span>3 rooms</span><span>No timer</span><span>Sound optional</span></div><p class="quiet-notice" data-quiet-notice hidden></p><button class="btn" id="startAdventure">Enter the story →</button><p class="saved-note">Your discoveries save as you explore.</p></div></div>
<div class="ov" id="chapterOv" aria-labelledby="chapterTitle"><div class="card"><span class="overline" id="chapterKicker">CHAPTER COMPLETE</span><h2 id="chapterTitle">The story opens.</h2><p id="chapterReveal"></p><button class="btn" id="nextChapter">Enter the next room →</button></div></div>
<div class="ov" id="helpOv" aria-labelledby="helpTitle"><div class="card"><span class="overline">YOUR FIELD GUIDE</span><h2 id="helpTitle">Look closer.</h2><p>Explore the three marked objects in each scene. Reopen any discovery in your field notes. Use the Scripture passage to solve the room’s puzzle.</p><p>Use Tab and Enter, or tap the buttons. Hints are always available. There is no timer, and sound is optional.</p><button class="btn" id="closeHelp">Back to the room</button></div></div>
<div class="ov" id="winOv" aria-labelledby="winTitle"><div class="card"><span class="finish-mark">ALL THREE ROOMS DISCOVERED</span><h2 id="winTitle">Hope found a home.</h2><p>Paul and Silas stayed to help. The jailer and his household heard God’s word, believed, and showed care.</p><p class="final-verse">“Believe on the Lord Jesus Christ, and thou shalt be saved, and thy house.”</p><span class="overline">ACTS 16:31 · KJV</span><p>Who could use an encouraging word from you today?</p><a class="btn" href="{{ route('kids') }}">Back to adventures →</a><button class="btn btn-ghost" id="replayAdventure">Explore again</button><p class="saved-note">The full story continues in Acts 16:32–34: the household hears the word, receives baptism, and rejoices.</p></div></div>
<script>
const LEVEL={id:{{ $level->id }}};
const ESCAPE_ROOMS=@json($rooms);
</script>
@include('kids.session')
@include('kids.audio')
<script>
const EscapeGame=(()=>{
  const $=id=>document.getElementById(id);let state={progress:0,discovered:[],placed:{}},busy=false,order=[],dials=[0,0,0,0],selectedItem=null,hint=0;
  const room=()=>ESCAPE_ROOMS[state.progress];
  const found=id=>(state.discovered||[]).includes(`${state.progress}:${id}`);
  const ready=()=>room().spots.every(s=>found(s.id));
  function button(text,cls,action){const b=document.createElement('button');b.type='button';b.textContent=text;b.className=cls;b.addEventListener('click',action);return b;}
  function feedback(text){$('puzzleFeedback').textContent=text;}
  function showNote(spot){$('clueTitle').textContent=spot.title;$('clueText').textContent=spot.text;$('clueQuote').textContent=spot.fragment;$('clueQuote').hidden=false;}
  function updateClues(){
    const r=room(),count=r.spots.filter(s=>found(s.id)).length;$('clueCount').textContent=`${count} / 3 clues`;
    $('collectedClues').replaceChildren();r.spots.filter(s=>found(s.id)).forEach(s=>$('collectedClues').append(button(s.name,'plain',()=>showNote(s))));
    $('hotspots').querySelectorAll('button').forEach(b=>{const yes=found(b.dataset.object);b.classList.toggle('found',yes);b.querySelector('.dot').textContent=yes?'✓':'+';b.setAttribute('aria-label',`${b.dataset.label}${yes?', discovered':''}`);b.disabled=busy;});
    $('checkPuzzle').disabled=busy||!ready()||(state.progress===0&&order.length!==5);
  }
  async function act(event){if(busy)return null;busy=true;updateClues();$('puzzleBody').querySelectorAll('button').forEach(b=>b.disabled=true);try{const result=await GameSession.move({room:state.progress,...event});state=result.state;return result;}finally{busy=false;}}
  async function inspect(spot){if(busy)return;if(!found(spot.id)){const result=await act({type:'inspect',object:spot.id});if(!result)return;GameAudio.play('tap');}showNote(spot);updateClues();renderPuzzle();feedback(ready()?'All clues found. Your puzzle is ready.':'Discovery saved in your field notes.');}
  function renderRoom(){
    const r=room();order=[];dials=[0,0,0,0];selectedItem=null;hint=0;
    $('roomPlace').textContent=`ROOM ${state.progress+1} OF 3 · ${r.place}`;$('roomTitle').textContent=r.title;$('roomIntro').textContent=r.intro;$('roomGoal').textContent=r.goal;$('puzzleTitle').textContent=r.puzzle;$('puzzleInstructions').textContent=r.instruction;$('passageRef').textContent=`Read ${r.reference}`;$('passageText').textContent=r.verse;$('passage').open=false;
    $('sceneArt').src='/kids-assets/escape/'+r.art;$('sceneArt').alt=r.place+' — explore '+r.spots.map(s=>s.name.toLowerCase()).join(', ');
    $('chapterTrack').setAttribute('aria-label',`Room ${state.progress+1} of 3`);Array.from($('chapterTrack').children).forEach((el,i)=>el.classList.toggle('done',i<=state.progress));
    $('hotspots').replaceChildren();r.spots.forEach(s=>{const b=button('','hotspot',()=>inspect(s));b.style.left=s.x+'%';b.style.top=s.y+'%';b.dataset.object=s.id;b.dataset.label=s.name;const dot=document.createElement('span');dot.className='dot';dot.setAttribute('aria-hidden','true');dot.textContent='+';const label=document.createElement('span');label.textContent=s.name;b.append(dot,label);$('hotspots').append(b);});
    $('clueTitle').textContent='Search the scene';$('clueText').textContent='Explore all three objects. Reopen your discoveries below whenever you need them.';$('clueQuote').hidden=true;$('hintText').hidden=true;$('hintButton').textContent='Need a hint?';feedback('');renderPuzzle();updateClues();
  }
  function renderPuzzle(){
    const r=room(),root=$('puzzleBody');root.replaceChildren();$('checkPuzzle').hidden=state.progress===2;
    if(state.progress===0){
      const placed=document.createElement('div');placed.className='answer-list';placed.setAttribute('aria-label','Your verse order');
      if(!order.length){const empty=document.createElement('span');empty.textContent='Your restored verse goes here…';empty.style.color='#99a8bc';placed.append(empty);}
      order.forEach((n,i)=>placed.append(button(r.options[n],'tile',()=>{order.splice(i,1);renderPuzzle();updateClues();$('puzzleBody').querySelector('.fragment-list button')?.focus();})));
      const choices=document.createElement('div');choices.className='fragment-list';r.options.forEach((text,i)=>{if(!order.includes(i))choices.append(button(text,'tile',()=>{if(!ready()){feedback('Find the three scene clues first.');return;}order.push(i);renderPuzzle();updateClues();(order.length===5?$('checkPuzzle'):$('puzzleBody').querySelector('.fragment-list button'))?.focus();}));});root.append(placed,choices);$('checkPuzzle').textContent='Restore the verse →';
    }else if(state.progress===1){
      const group=document.createElement('div');group.className='dials';r.dials.forEach((options,i)=>{const b=button('','dial',()=>{if(!ready()){feedback('Explore the doorway, chains, and lamp first.');return;}dials[i]=(dials[i]+1)%options.length;renderPuzzle();$('puzzleBody').querySelectorAll('.dial')[i].focus();});b.setAttribute('aria-label',`Word dial ${i+1}: ${options[dials[i]]}. Activate to turn.`);const word=document.createElement('span');word.textContent=options[dials[i]];const hint=document.createElement('small');hint.textContent='↻ TURN';b.append(word,hint);group.append(b);});root.append(group);$('checkPuzzle').textContent='Send the message →';
    }else{
      const items=document.createElement('div');items.className='fragment-list';Object.entries(r.items).forEach(([id,label])=>{if(state.placed?.[id])return;const b=button(label,'tile',()=>{if(!ready()){feedback('Explore all three table objects first.');return;}selectedItem=id;renderPuzzle();feedback(`Selected: ${label}. Choose its action below.`);});b.setAttribute('aria-pressed',String(selectedItem===id));items.append(b);});
      const targets=document.createElement('div');targets.className='targets';Object.entries(r.targets).forEach(([id,label])=>{const item=Object.keys(state.placed||{}).find(k=>state.placed[k]===id);const b=button(item?`${label} · ${r.items[item]} ✓`:label,'target'+(item?' placed':''),()=>{if(!selectedItem){feedback('Choose an object first.');return;}solve({item:selectedItem,target:id});});b.disabled=!!item;targets.append(b);});root.append(items,targets);
    }
  }
  async function solve(extra={}){
    if(!ready()||busy)return;const previous=state.progress,answer=previous===0?[...order]:previous===1?room().dials.map((choices,i)=>choices[dials[i]]):undefined;
    const result=await act({type:'solve',...(answer?{answer}:{}),...extra});if(!result)return;
    if(state.completed){GameAudio.play('win');$('winOv').classList.add('show');return;}
    if(state.progress>previous){GameAudio.play('match');$('chapterTitle').textContent=previous===0?'The doors open.':'A light in the darkness.';$('chapterReveal').textContent=ESCAPE_ROOMS[previous].reveal;$('chapterKicker').textContent=`ROOM ${previous+1} COMPLETE`;$('chapterOv').classList.add('show');return;}
    if(extra.item&&state.placed?.[extra.item]){selectedItem=null;GameAudio.play('match');}renderPuzzle();updateClues();feedback(state.feedback||'Keep exploring.');
  }
  $('checkPuzzle').addEventListener('click',()=>solve());
  $('hintButton').addEventListener('click',()=>{const hints=room().hints;$('hintText').textContent=hints[Math.min(hint,hints.length-1)];hint++;$('hintText').hidden=false;$('hintButton').textContent=hint<hints.length?'One more hint':'Show the hint';$('passage').open=true;});
  $('nextChapter').addEventListener('click',()=>{$('chapterOv').classList.remove('show');renderRoom();window.scrollTo({top:0,behavior:'instant'});$('roomTitle').setAttribute('tabindex','-1');$('roomTitle').focus();});
  $('helpButton').addEventListener('click',()=>$('helpOv').classList.add('show'));$('closeHelp').addEventListener('click',()=>$('helpOv').classList.remove('show'));
  document.addEventListener('keydown',e=>{if(e.key==='Escape')$('helpOv').classList.remove('show');});
  $('soundToggle').addEventListener('click',()=>GameAudio.toggle());
  $('startAdventure').addEventListener('click',()=>{$('introOv').classList.remove('show');$('hotspots').querySelector('button')?.focus();});
  $('replayAdventure').addEventListener('click',()=>location.reload());
  GameSession.ready().then(data=>{state=data.state;renderRoom();if(state.progress||state.discovered?.length)$('startAdventure').textContent='Continue your story →';$('introOv').classList.add('show');});
  return{inspect,solve};
})();
</script>
</body>
</html>
